INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(51911, 'Psalms 67:1', 'Psalms', 67, 1, 'ای خدایه، رحم وکړه په مونږ او برکت راکړه په ورین تندي وګوره مونږ ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms67_verse_1.mp3', '', 1761754199, 1761754199),
(51912, 'Psalms 67:2', 'Psalms', 67, 2, 'ترڅو چې ټوله دنیا وپېژني ستا لاره ترڅو چې ټول قومونه وپېژني ستا نجات بخښونکی ځواک', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms67_verse_2.mp3', '', 1761754199, 1761754199),
(51913, 'Psalms 67:3', 'Psalms', 67, 3, 'پرېږده چې خلک دې صفت وکړي خدایه پرېږده چې ټول خلک دې کاندي صفت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms67_verse_3.mp3', '', 1761754199, 1761754199),
(51914, 'Psalms 67:4', 'Psalms', 67, 4, 'پرېږده خوشحال شي ټول قومونه او سندرې د خوښۍ ووایي ځکه چې ته د ولسونو قضاوت کړې په انصاف سره او په دنیا کې لارښوونه د قومونو کوې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms67_verse_4.mp3', '', 1761754199, 1761754199),
(51915, 'Psalms 67:5', 'Psalms', 67, 5, 'پرېږده چې خلک دې صفت وکړي خدایه پرېږده چې ټول خلک دې کاندي صفت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms67_verse_5.mp3', '', 1761754199, 1761754199),
(51916, 'Psalms 67:6', 'Psalms', 67, 6, 'بیا ورکوي ځمکه به خپل حاصل خدای، زمونږه خدای به کړي نازل خپل برکت په مونږ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms67_verse_6.mp3', '', 1761754199, 1761754199),
(51917, 'Psalms 67:7', 'Psalms', 67, 7, 'خدای دې راکړي برکت مونږ ته پرېږده چې ټول خلک په هرځای کې ترې وېره وکړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms67_verse_7.mp3', '', 1761754199, 1761754199),
(51918, 'Psalms 50:1', 'Psalms', 50, 1, 'کوي خبرې څښتن خدای چې دی مطلق قادر ټولې دنیا نه خلک راغواړي له ختیځه تر لوېدیځه پورې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms50_verse_1.mp3', '', 1761754199, 1761754199),
(51919, 'Psalms 50:2', 'Psalms', 50, 2, 'د صهیون ښار چې په حسن کې کامل دی ځلیږي خدای ورڅخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms50_verse_2.mp3', '', 1761754199, 1761754199),
(51920, 'Psalms 50:3', 'Psalms', 50, 3, 'زمونږه خدای راځي خو خاموشه نه راځي د هغه مخکې سوځېدونکی اور وي او ګیرچاپېره ترې وي سخت توفان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms50_verse_3.mp3', '', 1761754199, 1761754199),
(51921, 'Psalms 50:4', 'Psalms', 50, 4, 'ځمکه او اسمان راغواړي د شاهدانو په حیث چې په خپل قوم باندې د هغه عدالت وویني', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms50_verse_4.mp3', '', 1761754199, 1761754199),
(51922, 'Psalms 50:5', 'Psalms', 50, 5, 'وایي: «راټول زما وفادار خلک کړئ د قربانۍ په ورکولو یې چې ما سره لوظ کړی دی»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms50_verse_5.mp3', '', 1761754199, 1761754199),
(51923, 'Psalms 50:6', 'Psalms', 50, 6, 'اسمانونه ورکوي دا خبرتیا چې خدای عادل دی ځکه چې خپله قاضي دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms50_verse_6.mp3', '', 1761754199, 1761754199),
(51924, 'Psalms 50:7', 'Psalms', 50, 7, 'ای زما قومه، زما خبرې واورئ ای اسراییلو، ستاسو ضد زه شاهدي به وایم زه یمه خدای، د ستاسو خدای یمه زه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms50_verse_7.mp3', '', 1761754199, 1761754199),
(51925, 'Psalms 50:8', 'Psalms', 50, 8, 'د قربانیو په خاطر زه تاسو نه رټمه او نه د هغو سوځېدونکو نذرانو په خاطر چې تل یې ماته راوړئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms50_verse_8.mp3', '', 1761754199, 1761754199),
(51926, 'Psalms 50:9', 'Psalms', 50, 9, 'ستاسو د کور غویو ته نه یم محتاج یا زه شپولو ته د نرانو وزو نه یم احتیاج', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms50_verse_9.mp3', '', 1761754199, 1761754199),
(51927, 'Psalms 50:10', 'Psalms', 50, 10, 'ټول حیوانات چې په ځنګل کې دي هغه زما دي هم په زرګونو غونډیو ټول څاروي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms50_verse_10.mp3', '', 1761754199, 1761754199),
(51928, 'Psalms 50:11', 'Psalms', 50, 11, 'پېژنم زه د غرونو ټول مرغان د پټیو ټول خزندګان زما دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms50_verse_11.mp3', '', 1761754199, 1761754199),
(51929, 'Psalms 50:12', 'Psalms', 50, 12, 'که چېرې وږی یم زه تاسو ته یې نه وایمه ځکه دنیا او چې په کې دي هغه ټول زما دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms50_verse_12.mp3', '', 1761754199, 1761754199),
(51930, 'Psalms 50:13', 'Psalms', 50, 13, 'ایا زه خورمه د غویانو غوښې؟ یا د وزو وینې څښم؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms50_verse_13.mp3', '', 1761754199, 1761754199),
(51931, 'Psalms 50:14', 'Psalms', 50, 14, 'شکر ادا کړئ د خدای دا ده قرباني د ستاسې هغه څه ورکړئ خدای تعالی ته چې منلي مو په نذر کې دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms50_verse_14.mp3', '', 1761754199, 1761754199),
(51932, 'Psalms 50:15', 'Psalms', 50, 15, 'د تکلیف په وخت کې ماته فریاد وکړئ زه به خلاصون درکړمه تاسو لره ثنا او صفت به کوئ تاسو زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms50_verse_15.mp3', '', 1761754199, 1761754199),
(51933, 'Psalms 50:16', 'Psalms', 50, 16, 'خو بدکاره ته خدای داسې وایي: «دی ستا څه کار چې زما حکمونه وایې؟ زما د لوظ په هکله ته کوې خبرې ولې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms50_verse_16.mp3', '', 1761754199, 1761754199),
(51934, 'Psalms 50:17', 'Psalms', 50, 17, 'اصلاح کېدو څخه انکار کوې ته زما خبرې غورځوې شاته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms50_verse_17.mp3', '', 1761754199, 1761754199),
(51935, 'Psalms 50:18', 'Psalms', 50, 18, 'هر غل چې وګورې ملګری یې شې او یوځای کېږې زناکارو سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms50_verse_18.mp3', '', 1761754199, 1761754199),
(51936, 'Psalms 50:19', 'Psalms', 50, 19, 'خلاصوې خوله دې شرارت باندې بې له دروغو بل څه نه وایې ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms50_verse_19.mp3', '', 1761754199, 1761754199),
(51937, 'Psalms 50:20', 'Psalms', 50, 20, 'دې ته تیار یې چې په خپل ورور دې تهمت پورې کړې او هم د خپلې مور د زوی پسې غیبت وکړې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms50_verse_20.mp3', '', 1761754199, 1761754199),
(51938, 'Psalms 50:21', 'Psalms', 50, 21, 'دا ټول کارونه تا کول او ما هېڅ ونه ویل نو ستا دا خیال ؤ چې زه ستا په شان یم خو اوس به زه تا رټم او کړم به تا تورن', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms50_verse_21.mp3', '', 1761754199, 1761754199),
(51939, 'Psalms 50:22', 'Psalms', 50, 22, 'تاسو چې زه یمه هېر کړی دې ته غوږ ونیسئ که نه نو تاسو به زه وداړمه هېڅوک به نه وي چې مو خلاص کاندي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms50_verse_22.mp3', '', 1761754199, 1761754199),
(51940, 'Psalms 50:23', 'Psalms', 50, 23, 'څوک چې د مننې قرباني کړي هغه ماته درناوی کوي هغه چې کړي خپله لاره سمه ورکوم نجات»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms50_verse_23.mp3', '', 1761754199, 1761754199),
(51941, 'Job 37:1', 'Job', 37, 1, 'په دې باندې هم زما زړۀ درزيږى، او ټوپونه وهى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job37_verse_1.mp3', '', 1761754199, 1761754199),
(51942, 'Job 37:2', 'Job', 37, 2, 'واورئ، واورئ، د خُدائ پاک د تندر آواز واورئ او د غړمبا آواز واورئ چې د هغۀ د خولې نه راځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job37_verse_2.mp3', '', 1761754199, 1761754199),
(51943, 'Job 37:3', 'Job', 37, 3, 'د ټول آسمان لاندې هغه دا پړق وهى، او د هغۀ رڼا د دُنيا ګوټونو ته رسيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job37_verse_3.mp3', '', 1761754199, 1761754199),
(51944, 'Job 37:4', 'Job', 37, 4, 'بيا د هغۀ آواز شور جوړ کړى، او د هغۀ د تندر آوازونه د شان او شوکت سره راشى، کله چې د هغۀ آواز واورېدے شى نو هغه رڼاګانې نۀ ايساروى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job37_verse_4.mp3', '', 1761754199, 1761754199),
(51945, 'Job 37:5', 'Job', 37, 5, 'خُدائ پاک د خپل آواز سره زبردست تندر راولى، هغه داسې لوئ کارونه کوى چې مونږ پرې نۀ پوهيږو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job37_verse_5.mp3', '', 1761754199, 1761754199),
(51946, 'Job 37:6', 'Job', 37, 6, 'ځکه چې هغه واورې ته وائى چې په زمکه وورېږه، او باران ته وائى چې وورېږه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job37_verse_6.mp3', '', 1761754199, 1761754199),
(51947, 'Job 37:7', 'Job', 37, 7, 'نو هر يو کس خپل کار بس کړى چې د هغۀ طاقت وګورى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job37_verse_7.mp3', '', 1761754199, 1761754199),
(51948, 'Job 37:8', 'Job', 37, 8, 'بيا ځنګلى ځناور خپلو پناه ګاهو ته لاړ شى او په خپلو غارونو کښې پاتې شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job37_verse_8.mp3', '', 1761754199, 1761754199),
(51949, 'Job 37:9', 'Job', 37, 9, 'د جنوب طرف نه طوفانى هوا راځى، او د شمال طرف نه د سختې هوا نه يخنى راځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job37_verse_9.mp3', '', 1761754199, 1761754199),
(51950, 'Job 37:10', 'Job', 37, 10, 'د خُدائ پاک ساه د اوبو نه واوره جوړوى، او ډېرې اوبۀ په واوره باندې بدلې شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job37_verse_10.mp3', '', 1761754199, 1761754199),
(51951, 'Job 37:11', 'Job', 37, 11, 'هغه وريځ د نمۍ نه ډکوى، او په وريځو کښې برېښنا پړقوى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job37_verse_11.mp3', '', 1761754199, 1761754199),
(51952, 'Job 37:12', 'Job', 37, 12, 'کله چې دا د خُدائ پاک په مرضۍ چليږى نو دا په ټوله دُنيا کښې د خُدائ پاک هر يو حُکم پوره کوى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job37_verse_12.mp3', '', 1761754199, 1761754199),
(51953, 'Job 37:13', 'Job', 37, 13, 'هغه دا کارونه ځکه کوى چې خلقو ته په کښې تکليف مِلاو شى يا کۀ نۀ ختمېدونکې مينه ورته ښائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job37_verse_13.mp3', '', 1761754199, 1761754199),
(51954, 'Job 37:14', 'Job', 37, 14, 'اے ايُوبه، دا واوره، ودرېږه او د خُدائ پاک په دې عجيبه عجيبه کارونو باندې سوچ وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job37_verse_14.mp3', '', 1761754199, 1761754199),
(51955, 'Job 37:15', 'Job', 37, 15, 'تا ته پته شته څۀ چې هغه طوفان څنګه قابو کوى، او د خپلې وريځې نه رڼا څنګه پړقوى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job37_verse_15.mp3', '', 1761754199, 1761754199),
(51956, 'Job 37:16', 'Job', 37, 16, 'تا ته پته شته چې وريځې په آسمان کښې څنګه روانې وى، دا د هغه چا عجيبه کارونه دى چې عِلم يې پوره دے،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job37_verse_16.mp3', '', 1761754199, 1761754199),
(51957, 'Job 37:17', 'Job', 37, 17, 'کله چې تاسو په خپلو جامو کښې سوزئ او د جنوب طرف ته هوا بنده شى او يو څيز هم نۀ خوځيږى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job37_verse_17.mp3', '', 1761754199, 1761754199),
(51958, 'Job 37:18', 'Job', 37, 18, 'هغه په آسمانونو کښې سترګې برېښوونکې رڼا ځلوى. ولې تاسو هغه شان کولے شئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job37_verse_18.mp3', '', 1761754199, 1761754199),
(51959, 'Job 37:19', 'Job', 37, 19, 'مونږ ته ووايئ چې هغۀ ته څۀ ووايو، زمونږ دماغ کار نۀ کوى چې خپله خبره بيان کړُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job37_verse_19.mp3', '', 1761754199, 1761754199),
(51960, 'Job 37:20', 'Job', 37, 20, 'خُدائ پاک دې خبر شى څۀ چې زۀ خبرې کول غواړم، زۀ داسې ولې وکړم چې د دې په وجه مې تباه کړى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job37_verse_20.mp3', '', 1761754199, 1761754199),
(51961, 'Job 37:21', 'Job', 37, 21, 'په هغه وخت کښې رڼا ته هيڅ څوک نۀ شى کتلے کله چې دا په آسمان کښې تکه سپينه وى، په کوم وخت کښې چې هوا وريځ بوځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job37_verse_21.mp3', '', 1761754199, 1761754199),
(51962, 'Job 37:22', 'Job', 37, 22, 'د شمال په طرف د سرو زرو جلوه ښکارى، د خُدائ پاک نه ګېرچاپېره لوئى، شان او شوکت تاو دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job37_verse_22.mp3', '', 1761754199, 1761754199),
(51963, 'Job 37:23', 'Job', 37, 23, 'مونږ د قادر مطلق خُدائ د طاقت تصور نۀ شُو کولے، خو هغه بيا هم د اِنصاف والا او صادق دے، هغه مونږ نۀ تباه کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job37_verse_23.mp3', '', 1761754199, 1761754199),
(51964, 'Job 37:24', 'Job', 37, 24, 'نو په دې وجه بنى آدم د هغۀ نه يريږى، او څوک چې ځان هوښيار ګڼى نو هغه يې پرواه نۀ کوى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job37_verse_24.mp3', '', 1761754199, 1761754199),
(51965, 'Isaiah 52:1', 'Isaiah', 52, 1, 'ای صهیونه، شه راویښ، راپاڅه خپل ځان قوي کړه ای سپېڅلی ښاره اورشلیمه، کالي واغونده د خپل شان او شوکت! په رښتیا به کافران او ناپاکه کسان بیا هېڅکله داخل نه شي ستا دروازو ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah52_verse_1.mp3', '', 1761754199, 1761754199),
(51966, 'Isaiah 52:2', 'Isaiah', 52, 2, 'ای اورشلیمه، ځان ته ټکان ورکړه، ازاد شه! له خاورو پورته شه او کښېنه په خپل تخت باندې ای اسیرانو د صهیون، وشلوئ د غلامۍ زنځیرونه د خپلو غاړو نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah52_verse_2.mp3', '', 1761754199, 1761754199),
(51967, 'Isaiah 52:3', 'Isaiah', 52, 3, 'نو څښتن داسې وایي: «تاسو په وړیا توګه خرڅ شوي وئ او هم به په وړیا توګه بېرته واخیستل شئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah52_verse_3.mp3', '', 1761754199, 1761754199),
(51968, 'Isaiah 52:4', 'Isaiah', 52, 4, 'څښتن تعالی داسې وایي: «ډېره موده مخکې زما قوم مصر ته تللی ؤ چې هلته د پردیو په توګه ژوند وکړي، وروسته اشوریانو هغوی اسیران کړل او بې سببه یې په هغوی ظلم کاوه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah52_verse_4.mp3', '', 1761754199, 1761754199),
(51969, 'Isaiah 52:5', 'Isaiah', 52, 5, 'او اوس په بابل کې هم په هغوی ظلم کیږي. هغوی په وړیا توګه غلامان شوي دي او د هغوی حاکمان په خپل ځان ویاړي او هر وخت زما نوم سپکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah52_verse_5.mp3', '', 1761754199, 1761754199),
(51970, 'Isaiah 52:6', 'Isaiah', 52, 6, 'خو هغه ورځ راتلونکې ده چې زما قوم به زما د نوم اقرار وکړي چې زه خدای یم. هو، هغوی به پوه شي چې زه دلته یم او په خپله د هغوی سره خبرې کوم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah52_verse_6.mp3', '', 1761754199, 1761754199),
(51971, 'Isaiah 52:7', 'Isaiah', 52, 7, 'څومره ښکلي دي د پیغام وړونکي قدمونه چې په غرونو دي روان چې راوړي زېری د خوشحالۍ او سولې هغه اعلان کړي د ژغورنې او صهیون ته وایي: «پاچاهي کوي ستا خدای»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah52_verse_7.mp3', '', 1761754199, 1761754199),
(51972, 'Isaiah 52:8', 'Isaiah', 52, 8, 'څوک چې ساتنه کړي د ښار، هغه چیغې وهي هغوی چیغې وهي له خوشحالۍ نه ځکه هغوی په خپلو سترګو ویني د څښتن راستنېدل صهیون ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah52_verse_8.mp3', '', 1761754199, 1761754199),
(51973, 'Isaiah 52:9', 'Isaiah', 52, 9, 'ای د اورشلیم کنډوالو، یوځای او په لوړ اواز د خوشحالۍ ووهئ چیغې! ځکه څښتن به وژغوري خپل ښار او خپلو خلکو ته به ورکړي تسلي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah52_verse_9.mp3', '', 1761754199, 1761754199),
(51974, 'Isaiah 52:10', 'Isaiah', 52, 10, 'څښتن به کار واخلي له خپل سپېڅلي ځواکه د ټولو قومونو مخکې وبه ګوري ټوله نړۍ زمونږ د خدای ژغورنه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah52_verse_10.mp3', '', 1761754199, 1761754199),
(51975, 'Isaiah 52:11', 'Isaiah', 52, 11, 'ځئ، لاړ شئ، ووځئ له دې ځایه! څوک چې سامان وړي د څښتن د کور له بابله ووځئ پاک کړئ ځانونه خپل او لاس مه وروړئ ناپاکه شي ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah52_verse_11.mp3', '', 1761754199, 1761754199),
(51976, 'Isaiah 52:12', 'Isaiah', 52, 12, 'دا ځل به ونه وځئ په بیړه تاسو له هغه ځایه تاسو به نه کوئ د تېښتې هڅه ځکه څښتن به ځي ستاسو نه مخکې او د شا له خوا به کړي ساتنه ستاسو د اسراییلو خدای', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah52_verse_12.mp3', '', 1761754199, 1761754199),
(51977, 'Isaiah 52:13', 'Isaiah', 52, 13, 'څښتن وایي: «ګورئ، په خپل کار کې بریالی به وي زما خدمتګار وي به سرلوړی او ډېر درناوی به یې کیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah52_verse_13.mp3', '', 1761754199, 1761754199),
(51978, 'Isaiah 52:14', 'Isaiah', 52, 14, 'خو کله چې ولید هغه ډېرو خلکو نو حیران شول هغوی ځکه بدرنګه یې څېره شوه دومره چې نه ښکاره کېدله د انسان په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah52_verse_14.mp3', '', 1761754199, 1761754199),
(51979, 'Isaiah 52:15', 'Isaiah', 52, 15, 'خو اوس به ډېر قومونه شي حیران هغه ته او چوپ به شي پاتې پاچاهان له حیرانتیا نه هغوی به وویني داسې شیان چې هېڅکله ورته نه وو ویل شوي هغوی به پوه شي داسې شیانو باندې چې یې نه وو اورېدلي مخکې»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah52_verse_15.mp3', '', 1761754199, 1761754199),
(51980, 'Isaiah 65:1', 'Isaiah', 65, 1, 'څښتن وویل: «زه دې ته تیار وم چې د خپلو خلکو دعاګانې قبولې کړم، خو هغوی دعا ونه کړه. زه دې ته تیار وم چې هغوی ما پیدا کړي، خو هغوی زما په لټه کې نه وو. ما ویل: ‹زه دلته یم، زه دلته یم›، خو بیاهم هغه قوم زما نوم نه یاداوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah65_verse_1.mp3', '', 1761754199, 1761754199),
(51981, 'Isaiah 65:2', 'Isaiah', 65, 2, 'ما ټوله ورځ خپله غېږه یو سرکښه قوم ته خلاصه کړې ده، خو هغوی په غلطو لارو روان دي او په کږو وږو نقشو پسې ګرځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah65_verse_2.mp3', '', 1761754199, 1761754199),
(51982, 'Isaiah 65:3', 'Isaiah', 65, 3, 'هغوی تل ما په قهر کوي. هغوی په خپلو باغونو کې بتانو ته قربانۍ وړاندې کوي او د خښتو د قربانۍ په ځایونو کې خوشبویي سوځوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah65_verse_3.mp3', '', 1761754199, 1761754199),
(51983, 'Isaiah 65:4', 'Isaiah', 65, 4, 'هغوی په هدېرو کې کښېني او په پټو ځایونو کې شپې تېروي، په دې خاطر چې د مړو له ارواحګانو نه مشوره وغواړي. د خوګ غوښه خورې او په لوښو کې یې د ناپاکو غوښو ښوروا ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah65_verse_4.mp3', '', 1761754199, 1761754199),
(51984, 'Isaiah 65:5', 'Isaiah', 65, 5, 'دا سرکښه خلک نورو ته وایي: ‹مونږ ته مه رانژدې کېږئ، ځکه مونږ ستاسو نه سپېڅلي یو.› زه داسې خلک نه شم زغملی، هغوی د داسې اور په شان دي چې ټوله ورځ بلیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah65_verse_5.mp3', '', 1761754199, 1761754199),
(51985, 'Isaiah 65:6', 'Isaiah', 65, 6, 'ګورئ، دلته زما په وړاندې د سرکښه خلکو عملونه ثبت شوي دي: ‹زه به نور غلی پاتې نه شم، بلکې هغوی ته به پوره سزا ورکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah65_verse_6.mp3', '', 1761754199, 1761754199),
(51986, 'Isaiah 65:7', 'Isaiah', 65, 7, 'زه به سرکښه خلکو ته نه یوازې د هغوی د ګناهونو له امله بلکې د هغوی د پلرونو او نیکونو د ګناهونو په خاطر به هم سزا ورکړم. ځکه چې هغوی په غرونو او غونډیو باندې خپلو بتانو ته خوشبویي سوځولې ده او زما سپکاوی یې کړی دی. نو له دې امله سرکښه خلکو ته به د هغوی د بدو کړنو په خاطر مناسبه سزا ورکړم.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah65_verse_7.mp3', '', 1761754199, 1761754199),
(51987, 'Isaiah 65:8', 'Isaiah', 65, 8, 'څښتن داسې وایي: «هېڅوک د انګورو ښه وږي له منځه نه وړي، بلکې د هغو څخه شراب جوړوي. خو زه هم خپل ټول قوم له منځه نه وړم او د خپلو خدمتګارانو ساتنه کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah65_verse_8.mp3', '', 1761754199, 1761754199),
(51988, 'Isaiah 65:9', 'Isaiah', 65, 9, 'زه د یعقوب د نسل څخه او د یهودا د قبیلې څخه اولادونه پیدا کوم چې زما د غرني هېواد خاوندان شي. څوک چې زما غوره شوي خدمتګاران دي، هلته به اوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah65_verse_9.mp3', '', 1761754199, 1761754199),
(51989, 'Isaiah 65:10', 'Isaiah', 65, 10, 'څوک چې زما په لټه کې دي، په لوېدیځ کې به د شارون ډاګ د هغوی د رمو څړځای او په ختیځ کې به یې د مصیبت دره د څارویو د څرولو ځای وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah65_verse_10.mp3', '', 1761754199, 1761754199),
(51990, 'Isaiah 65:11', 'Isaiah', 65, 11, 'خو تاسو چې ما پرېږدئ، زما سپېڅلی غر هېروئ، د ‹بخت› بت ته دسترخوان هواروئ او د ‹سرنوشت› بت ته د شرابو جامونه ډکوئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah65_verse_11.mp3', '', 1761754199, 1761754199),
(51991, 'Isaiah 65:12', 'Isaiah', 65, 12, 'تاسو به بد سرنوشت ولرئ او ټول به د حلالوونکي په وړاندې ټیټ شئ. ځکه کله چې ما په تاسو غږ وکړ، تاسو ځواب رانه کړ او کله چې مې ستاسو سره خبرې کولې، غوږ مو ورته نه نیوه، بلکې زما د سترګو په وړاندې مو بد کارونه کول. تاسو هغه لاره غوره کړه چې زما رضا نه وه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah65_verse_12.mp3', '', 1761754199, 1761754199),
(51992, 'Isaiah 65:13', 'Isaiah', 65, 13, 'نو بیا څښتن تعالی داسې وایي: «ګورئ، زما خدمتګاران به پرېمانه ډوډۍ وخوري، خو تاسو به وږي پاتې شئ. هغوی به د څښلو دپاره هرڅه ولري، خو تاسو به تږي اوسئ. هغوی به خوشحاله وي، خو تاسو به رسوا شئ او وبه شرمېږئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah65_verse_13.mp3', '', 1761754199, 1761754199),
(51993, 'Isaiah 65:14', 'Isaiah', 65, 14, 'زما خدمتګاران به د خوشحالۍ سندرې ووایي، خو تاسو به د زړه له درده چیغې ووهئ او د ویر ژړا به کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah65_verse_14.mp3', '', 1761754199, 1761754199),
(51994, 'Isaiah 65:15', 'Isaiah', 65, 15, 'ستاسو نوم به زما د غوره شوي قوم په منځ کې د یو لعنت په توګه وکارول شي. زه څښتن تعالی به تاسو له منځه یوسم، خو خپلو رښتینو خدمتګارانو ته به یو نوی نوم ورکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah65_verse_15.mp3', '', 1761754199, 1761754199),
(51995, 'Isaiah 65:16', 'Isaiah', 65, 16, 'نو هرڅوک چې په دې وطن کې د وفادار خدای په نوم د خپل ځان دپاره برکت وغواړي او یا قسم وخوري، پخواني کړاوونه به یې هېر شي او زما له سترګو څخه به پناه شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah65_verse_16.mp3', '', 1761754199, 1761754199),
(51996, 'Isaiah 65:17', 'Isaiah', 65, 17, 'څښتن وایي: «ګورئ، زه نوي اسمانونه او یوه نوې ځمکه پیدا کوم. ټول پخواني شیان به هېر شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah65_verse_17.mp3', '', 1761754199, 1761754199),
