(51998, 'Isaiah 65:19', 'Isaiah', 65, 19, 'اورشلیم او زما خلک چې د هغه ځای اوسېدونکي دي، هغوی به زما د خوشحالۍ سبب وګرځي. هلته به نوره ژړا او چیغې وانه ورېدل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah65_verse_19.mp3', '', 1761754199, 1761754199),
(51999, 'Isaiah 65:20', 'Isaiah', 65, 20, 'ماشومان به نور په وړوکتوب کې نه مړه کیږي او ټول خلک به خپل عمر پوره کوي. سل کلن خلک به په ځوانانو کې شمېرل کیږي او څوک چې سل کلنۍ ته نه رسیږي، هغوی به لعنتي شمېرل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah65_verse_20.mp3', '', 1761754199, 1761754199),
(52000, 'Isaiah 65:21', 'Isaiah', 65, 21, 'څوک چې کورونه جوړوي، نو په خپله به په کې واوسیږي او څوک چې د انګورو باغونه کري، نو د هغو انګور به وخوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah65_verse_21.mp3', '', 1761754199, 1761754199),
(52001, 'Isaiah 65:22', 'Isaiah', 65, 22, 'ځکه نور به زما د قوم کورونه او د انګورو باغونه د بل چا لاس ته ورنه شي. زما غوره شوي خلک به د ونو په شان ډېر اوږده عمرونه ولري. د خپل زیار حاصل به لاسته راوړي او په پوره توګه به ترې خوند واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah65_verse_22.mp3', '', 1761754199, 1761754199),
(52002, 'Isaiah 65:23', 'Isaiah', 65, 23, 'د هغوی زیار به بېځایه نه وي او د هغوی ماشومان به نور د بدبختۍ سره نه مخامخ کیږي. ځکه زه به هغوی او د هغوی اولادې ته تل برکت ورکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah65_verse_23.mp3', '', 1761754199, 1761754199),
(52003, 'Isaiah 65:24', 'Isaiah', 65, 24, 'حتی مخکې له دې چې هغوی ماته غږ وکړي، زه به ځواب ورکړم. مخکې له دې چې خپله دعا پای ته ورسوي، زه به هغه قبوله کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah65_verse_24.mp3', '', 1761754199, 1761754199),
(52004, 'Isaiah 65:25', 'Isaiah', 65, 25, 'لېوان او وري به په یوځای کې څریږي، زمریان به د غویانو په شان بوس خوري، خو د مارانو خواړه به خاوره وي. هغه وحشي حیوانات به نور زما په سپېڅلي غره صهیون باندې به هېچا او هېڅ شي ته زیان ونه رسوي او نه به یې له منځه یوسي.» څښتن داسې ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah65_verse_25.mp3', '', 1761754199, 1761754199),
(52005, 'Psalms 9:1', 'Psalms', 9, 1, 'زه به ستا شکر کوم د زړه له کومي ای څښتنه بیانوم به ټول کارونه عجیبه چې کړي تا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms9_verse_1.mp3', '', 1761754199, 1761754199),
(52006, 'Psalms 9:2', 'Psalms', 9, 2, 'زه به وایمه سندرې د خوښۍ ستا له سببه ستا په نامه باندې سندرې د ثنا به وایم ای خدای تعالی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms9_verse_2.mp3', '', 1761754199, 1761754199),
(52007, 'Psalms 9:3', 'Psalms', 9, 3, 'دښمنان زما چې مخ شي تا سره تښتي او خوري دوی تیندکونه هلاکیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms9_verse_3.mp3', '', 1761754199, 1761754199),
